-- Unavailability windows for Drivers and Vehicles (ADR-0034), owned by capacity.
-- drizzle-kit emits the audit values, the table, ENABLE RLS, the checks, the
-- composite foreign keys, the indexes, the audit check, and both policies.
-- FORCE RLS, the grants, and the Tenant listing function are hand-written.
-- No reason or kind column: a window says who is away, not why.
-- SELECT, INSERT, UPDATE for the routes; a window is removed by its mark.
-- DELETE for the daily retention job only, held by the restrictive policy
-- to windows that ended more than 90 days ago. ADR-0034 allows that grant.
ALTER TYPE "app"."audit_action" ADD VALUE 'unavailability.added';--> statement-breakpoint
ALTER TYPE "app"."audit_action" ADD VALUE 'unavailability.changed';--> statement-breakpoint
ALTER TYPE "app"."audit_action" ADD VALUE 'unavailability.removed';--> statement-breakpoint
CREATE TABLE "app"."unavailability_windows" (
	"tenant_id" uuid DEFAULT app.current_tenant_id() NOT NULL,
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"driver_id" uuid,
	"vehicle_id" uuid,
	"starts_at" timestamp with time zone NOT NULL,
	"ends_at" timestamp with time zone NOT NULL,
	"removed" boolean DEFAULT false NOT NULL,
	CONSTRAINT "unavailability_windows_one_owner" CHECK (num_nonnulls("app"."unavailability_windows"."driver_id", "app"."unavailability_windows"."vehicle_id") = 1),
	CONSTRAINT "unavailability_windows_order" CHECK ("app"."unavailability_windows"."starts_at" < "app"."unavailability_windows"."ends_at")
);
--> statement-breakpoint
ALTER TABLE "app"."unavailability_windows" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "app"."audit_entry" DROP CONSTRAINT "audit_entry_shape";--> statement-breakpoint
ALTER TABLE "app"."unavailability_windows" ADD CONSTRAINT "unavailability_windows_driver_fk" FOREIGN KEY ("tenant_id","driver_id") REFERENCES "app"."drivers"("tenant_id","id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "app"."unavailability_windows" ADD CONSTRAINT "unavailability_windows_vehicle_fk" FOREIGN KEY ("tenant_id","vehicle_id") REFERENCES "app"."vehicles"("tenant_id","id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
CREATE INDEX "unavailability_windows_driver_idx" ON "app"."unavailability_windows" USING btree ("tenant_id","driver_id","starts_at") WHERE "app"."unavailability_windows"."driver_id" is not null;--> statement-breakpoint
CREATE INDEX "unavailability_windows_vehicle_idx" ON "app"."unavailability_windows" USING btree ("tenant_id","vehicle_id","starts_at") WHERE "app"."unavailability_windows"."vehicle_id" is not null;--> statement-breakpoint
CREATE INDEX "unavailability_windows_ends_at_idx" ON "app"."unavailability_windows" USING btree ("tenant_id","ends_at");--> statement-breakpoint
