CREATE POLICY "tenant_isolation" ON "app"."unavailability_windows" AS PERMISSIVE FOR ALL TO "transferpro_app" USING ("app"."unavailability_windows"."tenant_id" = app.current_tenant_id()) WITH CHECK ("app"."unavailability_windows"."tenant_id" = app.current_tenant_id());--> statement-breakpoint
CREATE POLICY "unavailability_windows_retention_delete" ON "app"."unavailability_windows" AS RESTRICTIVE FOR DELETE TO "transferpro_app" USING ("app"."unavailability_windows"."ends_at" < now() - interval '90 days');
--> statement-breakpoint
ALTER TABLE "app"."unavailability_windows" FORCE ROW LEVEL SECURITY;
--> statement-breakpoint
REVOKE ALL ON TABLE "app"."unavailability_windows" FROM PUBLIC;
--> statement-breakpoint
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE "app"."unavailability_windows" TO "transferpro_app";
--> statement-breakpoint
-- The daily tick lists the Tenants that hold a window that ended before the
-- cutoff, so it can open one session per Tenant. It returns Tenant ids only.
CREATE FUNCTION "app"."tenants_with_unavailability_ended_before"(p_before timestamp with time zone)
RETURNS TABLE (tenant_id uuid)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
  select distinct w.tenant_id
  from app.unavailability_windows as w
  where w.ends_at < p_before
$$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION "app"."tenants_with_unavailability_ended_before"(timestamp with time zone) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION "app"."tenants_with_unavailability_ended_before"(timestamp with time zone) TO "transferpro_app";
